INSERT INTO public.kpi_query_registry (query_id, sql, max_params, note) VALUES
    ('brand_specific_kisqali_oncologist_reach', $kpi$SELECT base.*, (SELECT MAX(trigger_timestamp) FROM (SELECT * FROM triggers WHERE is_synthetic = false) triggers)::date AS data_through FROM (WITH oncologists AS (SELECT COUNT(DISTINCT hcp_id) AS total FROM (SELECT * FROM hcp_profiles WHERE is_synthetic = false) hcp_profiles WHERE specialty ILIKE '%oncolog%'), engaged AS (SELECT COUNT(DISTINCT t.hcp_id) AS total FROM (SELECT * FROM triggers WHERE is_synthetic = false) t INNER JOIN (SELECT * FROM hcp_profiles WHERE is_synthetic = false) hp ON hp.hcp_id = t.hcp_id WHERE hp.specialty ILIKE '%oncolog%' AND t.brand_id = 'Kisqali' AND t.trigger_timestamp >= (SELECT MAX(trigger_timestamp) FROM (SELECT * FROM triggers WHERE is_synthetic = false) triggers) - INTERVAL '90 days') SELECT engaged.total::float / NULLIF(oncologists.total, 0) AS reach FROM oncologists, engaged) base$kpi$, 0, $note$M4: default-exclude synthetic; 089 frontier-anchored (window ends at domain MAX, not NOW())$note$),
    ('brand_specific_kisqali_oncologist_reach_include_synthetic', $kpi$SELECT base.*, (SELECT MAX(trigger_timestamp) FROM triggers)::date AS data_through FROM (WITH oncologists AS (SELECT COUNT(DISTINCT hcp_id) AS total FROM hcp_profiles WHERE specialty ILIKE '%oncolog%'), engaged AS (SELECT COUNT(DISTINCT t.hcp_id) AS total FROM triggers t INNER JOIN hcp_profiles hp ON hp.hcp_id = t.hcp_id WHERE hp.specialty ILIKE '%oncolog%' AND t.brand_id = 'Kisqali' AND t.trigger_timestamp >= (SELECT MAX(trigger_timestamp) FROM triggers) - INTERVAL '90 days') SELECT engaged.total::float / NULLIF(oncologists.total, 0) AS reach FROM oncologists, engaged) base$kpi$, 0, $note$M4 opt-in: INCLUDES synthetic (validation runs only); 089 frontier-anchored (window ends at domain MAX, not NOW())$note$),
    ('brand_specific_remi_intent_delta_fallback', $kpi$SELECT base.*, (SELECT MAX(survey_date) FROM (SELECT * FROM hcp_intent_surveys WHERE is_synthetic = false) hcp_intent_surveys)::date AS data_through FROM (SELECT AVG(intent_to_prescribe_change) AS intent_delta FROM (SELECT * FROM hcp_intent_surveys WHERE is_synthetic = false) hcp_intent_surveys WHERE brand::text = 'Remibrutinib' AND survey_date >= (SELECT MAX(survey_date) FROM (SELECT * FROM hcp_intent_surveys WHERE is_synthetic = false) hcp_intent_surveys) - INTERVAL '90 days' AND intent_to_prescribe_change IS NOT NULL) base$kpi$, 0, $note$M4: default-exclude synthetic; 089 frontier-anchored (window ends at domain MAX, not NOW())$note$),
